        for k in range(W-1-max(b for _,b in c),-1,-1):
            pos={(a,b+k) for a,b in c}
            if any(x>=W for x,_ in pos) : pass
            if pos & occ: continue
            # contact check
            good=True
            for a,b in c:
                for da in (-1,0,1):
